<script lang="ts">
  import { page } from '$app/state';
  import { app } from '$lib/state.svelte';
  import { dataService } from '$lib/data/service';
  import { date, number, progress } from '$lib/domain';
  import { verificationLabel } from '$lib/verification';
  import type { VerificationStatus } from '$lib/types';
  import Indicators from '../../_components/Indicators.svelte';
  import Badge from '$lib/components/Badge.svelte';
  import Icon from '$lib/components/Icon.svelte';
  import Empty from '$lib/components/Empty.svelte';
  import Progress from '$lib/components/Progress.svelte';
  import Modal from '$lib/components/Modal.svelte';

  let search = $state('');
  let status = $state<VerificationStatus>('pending');
  let selectedId = $state('');
  let note = $state('');
  let decision = $state<'approved' | 'revision' | null>(null);
  let openedLink = $state('');
  const submissions = $derived(app.data!.submissions ?? []);
  const campus = (id: string) => app.data!.campuses.find(c => c.id === id)!;
  const definition = (id: string) => app.data!.definitions.find(d => d.id === id)!;
  const rows = $derived(submissions.filter(s => s.status === status && `${campus(s.campusId).name} ${campus(s.campusId).acronym ?? ""} ${campus(s.campusId).city ?? ""} ${campus(s.campusId).region}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => status === 'pending' ? a.submittedAt.localeCompare(b.submittedAt) || a.id.localeCompare(b.id) : (b.reviewedAt ?? '').localeCompare(a.reviewedAt ?? '')));
  const selected = $derived(rows.find(s => s.id === selectedId) ?? rows[0]);
  const activeSubmissionId = $derived(selected?.id);
  const gaps = $derived(selected?.indicators.filter(i => i.current < i.target).sort((a, b) => progress(a) - progress(b)) ?? []);
  const comments = $derived(selected ? app.data!.feedback.filter(f => f.campusId === selected.campusId) : []);
  const unresolved = $derived(comments.filter(f => f.requiresRevision && f.state !== 'closed'));
  $effect(() => {
    const id = page.url.searchParams.get('submission');
    const item = submissions.find(s => s.id === id);
    if (item && id !== openedLink) { selectedId = item.id; status = item.status; openedLink = id!; }
  });
  $effect(() => { activeSubmissionId; note = ''; decision = null; });
  async function review() {
    if (!selected || !decision) return;
    if (await app.mutate(() => dataService.reviewDeb(app.session!, selected.id, decision!, note), decision === 'approved' ? 'Data DEB disetujui dan kampus telah diberi notifikasi.' : 'Permintaan revisi dikirim ke kampus.')) decision = null;
  }
</script>

<svelte:head><title>Review Kampus · Digitalisasi DEB</title></svelte:head>
<div class="page-heading"><div><span class="eyebrow">RUANG REVIEW KAMPUS</span><h1>Tinjauan &amp; Konfirmasi DEB</h1><p>Periksa data yang dikirim kampus, beri catatan per indikator, lalu setujui atau minta revisi.</p></div><Badge tone="blue">{submissions.filter(s => s.status === 'pending').length} menunggu</Badge></div>
<div class="review-status-strip" aria-label="Ringkasan review">
  {#each [{value: 'pending', label: 'Menunggu tinjauan', icon: 'clock', note: 'Siap diperiksa Admin PF'}, {value: 'approved', label: 'Sudah dikonfirmasi', icon: 'check', note: 'Tersimpan dalam riwayat'}, {value: 'revision', label: 'Dikembalikan ke kampus', icon: 'edit', note: 'Perbaikan oleh pemilik data'}] as item}<button class:current={status === item.value} onclick={() => { status = item.value as VerificationStatus; search = ''; }}><span class={`status-icon ${item.value}`}><Icon name={item.icon}/></span><span class="status-copy"><small>{item.label}</small><strong>{submissions.filter(s => s.status === item.value).length}<span>pengajuan</span></strong><span>{item.note}</span></span><Icon name="arrow" size={16}/></button>{/each}
</div>
<div class="verification-layout">
  <section class="panel queue" aria-label="Daftar pengajuan">
    <div class="queue-heading"><h2>Kiriman kampus</h2><p>Paling lama menunggu ditampilkan lebih dulu.</p><label class="search-field"><Icon name="search" size={17}/><input aria-label="Cari pengajuan kampus" placeholder="Cari kampus atau wilayah…" bind:value={search}/></label><select aria-label="Status pengajuan" bind:value={status}>{#each ['pending', 'approved', 'revision'] as value}<option value={value}>{verificationLabel[value as VerificationStatus]} ({submissions.filter(s => s.status === value).length})</option>{/each}</select></div>
    <div class="queue-list">{#each rows as row}<button class="queue-item" class:chosen={row.id === selected?.id} aria-pressed={row.id === selected?.id} onclick={() => { selectedId = row.id; }}><strong>{campus(row.campusId).name}</strong><span>{campus(row.campusId).region}</span><div><Badge tone={row.status === 'pending' ? 'blue' : row.status === 'approved' ? 'green' : 'amber'}>Pengajuan #{row.version}</Badge><small>{row.simulated ? 'Simulasi' : 'Isian kampus'}</small></div><small>Dikirim {date(row.submittedAt)}</small></button>{:else}<p class="queue-empty">Tidak ada pengajuan yang cocok.</p>{/each}</div>
  </section>
  <div class="review-content">
    {#if selected}
      <section class="panel review-summary"><div class="row-between"><div><span class="eyebrow">PENGAJUAN #{selected.version}</span><h2>{campus(selected.campusId).name}</h2><p>{campus(selected.campusId).region} · Dikirim {date(selected.submittedAt)}</p></div><Badge tone={selected.status === 'approved' ? 'green' : selected.status === 'revision' ? 'amber' : 'blue'}>{verificationLabel[selected.status]}</Badge></div>
        <div class="review-metrics"><div><small>Indikator dikirim</small><strong>{selected.indicators.length}</strong></div><div><small>Target belum tercapai</small><strong>{gaps.length}</strong></div><div><small>Feedback revisi aktif</small><strong>{unresolved.length}</strong></div></div>
        <div class="info-note"><Icon name="verifikasi"/><div><strong>Admin meninjau dan mengonfirmasi</strong><p>Nilai adalah isian kampus dan bersifat baca saja. Konfirmasi memverifikasi data pengajuan, bukan menetapkan kelulusan atau kenaikan kelas DEB.</p></div></div>
        <a class="text-link" href={`/admin/campuses/${selected.campusId}`}>Buka profil dan proposal kampus <Icon name="arrow" size={15}/></a>
      </section>
      <section class="panel gap-panel"><div class="row-between"><h2>Kesenjangan terhadap target</h2><small>Target simulasi</small></div>{#if gaps.length}<p>{gaps.length} indikator belum mencapai target. Menampilkan maksimal 6 capaian terendah.</p><div class="gap-list">{#each gaps.slice(0, 6) as item}<div><div class="row-between"><span>{definition(item.definitionId).name}</span><strong>{number(item.current)} / {number(item.target)} {definition(item.definitionId).unit}</strong></div><Progress value={progress(item)} label={definition(item.definitionId).name}/></div>{/each}</div>{:else}<p>Seluruh indikator pada pengajuan ini sudah mencapai target simulasi.</p>{/if}</section>
      {#if selected.status === 'pending'}
        <div class="review-indicators"><h2>Indikator yang ditinjau</h2><p>Buka Tinjau untuk membaca catatan kampus dan memberi feedback per indikator.</p>{#key selected.id}<Indicators campusId={selected.campusId} embedded/>{/key}</div>
        <section class="panel comments-panel"><div class="row-between"><h2>Feedback kampus ini</h2><Badge tone="amber">{unresolved.length} revisi aktif</Badge></div>{#each comments as comment}<article><div class="row-between"><strong>{definition(app.data!.indicators.find(i => i.id === comment.indicatorId)!.definitionId).name}</strong><small>{comment.state === 'closed' ? 'Selesai' : comment.state === 'responded' ? 'Sudah ditanggapi' : 'Menunggu revisi'}</small></div><p class="pre-wrap">{comment.text}</p>{#if comment.state !== 'closed'}<button class="text-link" disabled={app.busy} onclick={() => app.mutate(() => dataService.closeFeedback(app.session!, comment.id), 'Feedback ditandai selesai.')}>Tandai selesai</button>{/if}</article>{:else}<p>Belum ada feedback untuk kampus ini.</p>{/each}</section>
        <section class="panel decision-panel"><h2>Hasil tinjauan</h2><p>Tinjau seluruh data dan feedback sebelum memberikan keputusan.</p><label>Catatan keputusan<textarea rows="4" maxlength="5000" bind:value={note} placeholder="Wajib untuk permintaan revisi. Sebutkan indikator dan data yang perlu diperbaiki."></textarea></label>{#if unresolved.length}<p class="decision-help">Selesaikan feedback revisi aktif sebelum menyetujui, atau kembalikan pengajuan ke kampus melalui Minta Revisi.</p>{/if}<div class="button-row"><button class="button" disabled={app.busy || unresolved.length > 0} onclick={() => decision = 'approved'}><Icon name="check" size={17}/>Konfirmasi data</button><button class="button secondary" disabled={app.busy || !note.trim()} onclick={() => decision = 'revision'}>Minta Revisi</button></div><small>Keputusan tersimpan dalam riwayat pengajuan dan dikirim ke notifikasi kampus.</small></section>
      {:else}
        <section class="panel decision-panel"><h2>Keputusan Admin PF</h2><p>{selected.reviewedBy} · {date(selected.reviewedAt!)}</p><p class="pre-wrap">{selected.decisionNote || 'Data pengajuan telah disetujui.'}</p><details><summary>Lihat arsip nilai yang dikirim</summary><div class="table-scroll"><table><thead><tr><th>Indikator</th><th>Aktual</th><th>Target</th><th>Catatan kampus</th></tr></thead><tbody>{#each selected.indicators as item}<tr><td>{definition(item.definitionId).name}</td><td>{number(item.current)}</td><td>{number(item.target)}</td><td class="pre-wrap">{item.note || '—'}</td></tr>{/each}</tbody></table></div></details></section>
      {/if}
    {:else}<section class="panel"><Empty title={search ? 'Pengajuan tidak ditemukan' : status === 'pending' ? 'Antrean sudah selesai' : 'Belum ada riwayat keputusan'} description={search ? 'Coba nama kampus atau wilayah lain.' : 'Pengajuan yang dikirim kampus akan muncul di antrean ini.'} icon="verifikasi"/></section>{/if}
  </div>
</div>
{#if decision && selected}<Modal title={decision === 'approved' ? 'Setujui pengajuan DEB?' : 'Kembalikan untuk revisi?'} onclose={() => { if (!app.busy) decision = null; }}><p><strong>{campus(selected.campusId).name} · Pengajuan #{selected.version}</strong></p><p>{decision === 'approved' ? 'Data pengajuan akan ditandai Terverifikasi dan dikeluarkan dari antrean.' : 'Kampus dapat memperbaiki indikator dan mengirim ulang pengajuannya.'}</p>{#if note.trim()}<p class="pre-wrap">{note}</p>{/if}<div class="dialog-actions"><button class="button secondary" disabled={app.busy} onclick={() => decision = null}>Batal</button><button class="button" disabled={app.busy} onclick={review}>Konfirmasi keputusan</button></div></Modal>{/if}

<style>
  .review-status-strip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0 0 26px}.review-status-strip>button{display:flex;align-items:center;gap:15px;text-align:left;padding:21px;border:1px solid #e0e7d9;background:#fff;border-radius:14px;cursor:pointer;color:#30482e;transition:border-color .15s,box-shadow .15s}.review-status-strip>button:hover,.review-status-strip>button.current{border-color:#8aa474;box-shadow:0 4px 14px #29442108}.status-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#edf2e7;flex-shrink:0}.status-icon.pending{background:#edf3fa;color:#507698}.status-icon.revision{background:#faf0dd;color:#a67c31}.status-copy{flex:1;min-width:0}.status-copy small{display:block;font-size:11px;color:#586d51}.status-copy strong{display:flex;align-items:baseline;gap:8px;font-size:29px;margin:7px 0;color:#294426}.status-copy strong span{font-size:10px;font-weight:500;color:#687b60}.status-copy>span{font-size:10px;color:#75816f}
  .verification-layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px;align-items:start}.queue{position:sticky;top:90px}.queue-heading{padding:20px;border-bottom:1px solid #e3e9df}.queue h2,.review-content h2{font-size:16px;line-height:1.5}.queue-heading p,.review-content p{font-size:12px;line-height:1.8;color:#61715f;margin:8px 0 16px}.queue-heading .search-field{margin:16px 0 12px;width:100%}.queue-heading input{min-width:0}.queue-heading select{width:100%;font-size:12px}.queue-list{max-height:calc(100dvh - 340px);min-height:150px;overflow-y:auto;padding:10px}.queue-item{display:flex;flex-direction:column;gap:8px;width:100%;padding:15px;text-align:left;border:1px solid transparent;background:transparent;border-radius:10px;margin-bottom:6px;color:#243d32;cursor:pointer}.queue-item:hover{background:#f5f8f2}.queue-item.chosen{background:#f0f6e9;border-color:#789764;box-shadow:inset 3px 0 #65894c}.queue-item strong{font-size:12px;line-height:1.7}.queue-item>span,.queue-item small{font-size:10px;color:#64735f}.queue-item>div{display:flex;justify-content:space-between;gap:8px;align-items:center}.queue-empty{padding:18px;font-size:12px}.review-content{min-width:0;display:grid;gap:22px}.review-summary,.gap-panel,.comments-panel,.decision-panel{padding:24px}.row-between{gap:12px;flex-wrap:wrap}.review-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.review-metrics>div{border:1px solid #e1e9d9;border-radius:10px;padding:16px}.review-metrics small{display:block;font-size:11px;color:#61715f}.review-metrics strong{display:block;font-size:28px;margin-top:8px}.review-summary .info-note{margin:0 0 18px}.review-summary .info-note p{margin-bottom:0}.gap-list{display:grid;gap:18px}.gap-list .row-between{font-size:11px;margin-bottom:8px}.gap-list strong{font-size:10px;font-weight:500;color:#61715f}.gap-panel small,.comments-panel small,.decision-panel small{font-size:11px;color:#61715f}.review-indicators{min-width:0}.review-indicators :global(.toolbar){flex-wrap:wrap;padding:16px;gap:10px}.review-indicators :global(.category-tabs){overflow-x:auto;white-space:nowrap;padding:0 16px}.review-indicators :global(.table-scroll table){min-width:760px}.comments-panel article{border-top:1px solid #e3e9df;padding:16px 0}.comments-panel article:first-of-type{margin-top:16px}.comments-panel article strong{font-size:12px}.decision-panel label{display:flex;flex-direction:column;align-items:stretch;gap:10px;margin:22px 0 18px;font-size:13px;font-weight:600}.decision-panel textarea{display:block;box-sizing:border-box;width:100%;min-height:156px;padding:16px;font-size:13px;font-weight:400;line-height:1.8;resize:vertical;background:#fcfdfb;border:1px solid #d6e1ce;border-radius:10px}.decision-panel textarea::placeholder{color:#819079}.decision-panel .button-row{gap:12px;margin-top:20px}.decision-panel small{display:block;margin-top:18px;line-height:1.8}.decision-help{color:#90651c!important}.decision-panel .button-row{flex-wrap:wrap}.decision-panel summary{cursor:pointer;font-size:13px;padding:12px 0}.decision-panel td{min-width:100px}.decision-panel td:last-child{min-width:220px}.decision-panel details{min-width:0}
  @media(max-width:1200px){.verification-layout{grid-template-columns:minmax(0,1fr)}.queue{position:static}.queue-list{max-height:250px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.queue-heading{display:flex;flex-wrap:wrap;align-items:center;gap:12px}.queue-heading p{width:100%;margin:0}.queue-heading .search-field{flex:1;margin:0;min-width:180px}.queue-heading select{width:auto}.queue-item{margin:0}}
  @media(max-width:800px){.review-status-strip{gap:8px}.review-status-strip>button{padding:13px;gap:10px}.status-icon,.review-status-strip>button> :global(svg),.status-copy>span{display:none}.status-copy strong{font-size:24px}.status-copy strong span{display:none}.status-copy small{font-size:10px;line-height:1.6}}
  @media(max-width:600px){.queue-list{grid-template-columns:1fr;max-height:235px}.review-summary,.gap-panel,.comments-panel,.decision-panel{padding:18px}.review-metrics{gap:7px}.review-metrics>div{padding:10px}.review-metrics small{font-size:10px}.review-metrics strong{font-size:24px}.queue-heading select{width:100%}.decision-panel .button-row .button{width:100%}}
</style>
